preConditionHook:
// THE TREND LINE, one construction shared by the whole lines/channels family
// (decided in slice B01, carried here unchanged): the BULL trend line runs
// through the two most recent CONFIRMED swing LOWS, the BEAR trend line through
// the two most recent confirmed swing HIGHS, deliberately NOT parallel. The
// pivot scan is INLINED rather than reaching into SwingHigh.json -- rules in
// this corpus never reference each other -- and mirrors the EL twin's SwingLow
// / SwingLowBar / SwingHigh / SwingHighBar at Occurrence 1 and 2.
//
// MEASURED, EL_Swing_Probe.txt / el_swing_output1.txt (@ES 60 min): the pivot
// test is MIXED -- AT OR ABOVE the swingStrength OLDER bars, STRICTLY ABOVE the
// swingStrength NEWER bars -- so a flat top yields exactly one pivot, the later
// of the equal bars; bars-ago indexing makes the SMALLER index the NEWER bar,
// so the strict half is the k < j loop. The confirmation lag is exactly
// swingStrength bars, never 0 or 1. pivotLookback is EL's Length (offsets
// 0..pivotLookback-1 inclusive) and the neighbourhood test reaches
// swingStrength bars PAST the window, so the deepest index the scan touches is
// pivotLookback - 1 + swingStrength. A window with no pivot returns the -1
// SENTINEL, guarded below. Occurrence 3+ is UNMEASURED and never asked for. The
// comparisons carry the 2.22e-12 relational tolerance, hence el_gt / el_ge. The
// low side's tie sense is the mirror of the measured high-side rule. No
// WFSafe_SwingHigh exists, so plain EL governs.
//
// MEASURED, EL_TLValue_Probe.txt: TLValue is the two-point line anchored at the
// FIRST pair, Slope = (P2 - P1) / (B2 - B1); value = P1 + (target - B1) *
// Slope, extrapolating freely past both anchors -- which is what lets it be
// read at an OLDER bar inside the loop below. Bars-ago convention, so the OLDER
// pivot (LARGER bars-ago) is P1/B1, the zero-drift spelling. Bar1 = Bar2
// silently returns 0.0, so B1 != B2 is guarded. The slope is hoisted out of the
// per-target arithmetic where the EL twin recomputes it inside each TLValue
// call; identical doubles, same line bit for bit.
//
// THIS RULE: bars HUGGING the line. Price has come within touchTolAtr x ATR of
// the projected line on at least minTouches of the last windowBars bars AND has
// never drifted more than maxDistanceAtr x ATR from it over that window.
// Brooks reads the pattern as an imminent break -- or, less often, an
// acceleration -- so the DIRECTION of the resolution is deliberately not
// encoded and this stays a filter.
//
// The distance is the MAGNITUDE of the gap between the bar's own near extreme
// and the line (low against the bull line, high against the bear line), so a
// bar that pokes THROUGH still counts as a touch while the poke is inside the
// tolerance. That is std::fabs, EL's AbsValue.
//
// THE PIVOTS ARE THE CURRENT ONES, not the pivots as they stood at bar kk;
// re-deriving them per bar is not expressible in EL, so the line is re-read at
// each bar of the window through TLValue's free extrapolation.
//
// ATR is read once at bar 0 and held fixed across the window: MultiWalk's
// accumulator advances per CALL SITE, so a per-bar re-read would be a second
// call site and a different number.
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration
// is a redefinition when this rule is placed twice in one strategy.
// Every one is fully assigned each bar before it is read.
pivS = (int)swingStrength;
pivW = (int)pivotLookback;
loP1 = -1.0;
loB1 = -1.0;
loP2 = -1.0;
loB2 = -1.0;
foundLo = 0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool ok = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_lt(low[j], low[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivS; ++k) {
            if (!el_le(low[j], low[k])) { ok = false; break; }
        }
    }
    if (ok) {
        ++foundLo;
        if (foundLo == 1) { loP2 = low[j]; loB2 = (double)j; }
        else { loP1 = low[j]; loB1 = (double)j; break; }
    }
}
hiP1 = -1.0;
hiB1 = -1.0;
hiP2 = -1.0;
hiB2 = -1.0;
foundHi = 0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool ok = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_gt(high[j], high[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivS; ++k) {
            if (!el_ge(high[j], high[k])) { ok = false; break; }
        }
    }
    if (ok) {
        ++foundHi;
        if (foundHi == 1) { hiP2 = high[j]; hiB2 = (double)j; }
        else { hiP1 = high[j]; hiB1 = (double)j; break; }
    }
}
haveLoLine = (foundLo == 2) && (loB1 != loB2);
haveHiLine = (foundHi == 2) && (hiB1 != hiB2);
loSlope = 0.0;
hiSlope = 0.0;
if (haveLoLine) loSlope = (loP2 - loP1) / (loB2 - loB1);
if (haveHiLine) hiSlope = (hiP2 - hiP1) / (hiB2 - hiB1);
// WFSafe_AvgTrueRange: MultiWalk's ROLLING accumulator, ported from
// AtrProfitTarget. Seeded with a full sum on the first calculated bar or when
// the length changes, and updated thereafter as TWO statements -- EL evaluates
// S[1] + in - out left to right, and folding it to S += in - out rounds
// differently. The local counter is atrLen; atrLength is this rule's INPUT.
if (atrLen != (int)atrLength) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLength; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLen = (int)atrLength;
} else {
    const int out = (int)atrLength;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atrVal = atrSum / (int)atrLength;
touchesLo = 0;
touchesHi = 0;
maxDistLo = 0.0;
maxDistHi = 0.0;
for (int kk = 0; kk <= (int)windowBars - 1; ++kk) {
    if (haveLoLine) {
        dLo = std::fabs(low[kk] - (loP1 + ((double)kk - loB1) * loSlope));
        if (el_le(dLo, touchTolAtr * atrVal)) ++touchesLo;
        if (el_gt(dLo, maxDistLo)) maxDistLo = dLo;
    }
    if (haveHiLine) {
        dHi = std::fabs(high[kk] - (hiP1 + ((double)kk - hiB1) * hiSlope));
        if (el_le(dHi, touchTolAtr * atrVal)) ++touchesHi;
        if (el_gt(dHi, maxDistHi)) maxDistHi = dHi;
    }
}
